int main(){using namespace digitor;LensFrame in{3,3,{}};in.pixels.resize(9);for(std::size_t i=0;i<9;++i)in.pixels[i]={float(i)/8.0f,0.5f,1.0f-float(i)/8.0f,1.0f};LensDistortionSettings s;s.k1=-0.18f;s.k2=0.03f;s.edge_mode=LensEdgeMode::clamp;LensFrame a,b;auto ra=apply_lens_distortion_reference(in,a,s);auto rb=apply_lens_distortion_reference(in,b,s);if(ra.status!=LensStatus::ready)return 1;if(ra.digest!=rb.digest)return 2;if(a.pixels.size()!=in.pixels.size())return 3;LensDispatchPacket p;p.backend=LensBackend::vulkan;p.width=3;p.height=3;p.input_handle=1;p.output_handle=2;p.command_handle=3;p.settings=s;if(dispatch_lens_distortion_gpu(p,{}).status!=LensStatus::backend_unavailable)return 4;if(dispatch_lens_distortion_gpu(p,[](const auto&){return true;}).status!=LensStatus::ready)return 5;p.command_handle=0;if(dispatch_lens_distortion_gpu(p,[](const auto&){return true;}).status!=LensStatus::invalid)return 6;std::vector<float> packed(36),out(36);for(std::size_t i=0;i<9;++i){packed[i*4]=in.pixels[i].r;packed[i*4+1]=in.pixels[i].g;packed[i*4+2]=in.pixels[i].b;packed[i*4+3]=1;}DigitorLensDistortionSettings c{};c.mode=1;c.edge_mode=1;c.k1=s.k1;c.k2=s.k2;c.center_x=.5f;c.center_y=.5f;c.scale=1;c.aspect=1;c.high_quality=1;std::uint64_t digest{};if(digitor_lens_distortion_rgba32f(packed.data(),out.data(),3,3,&c,&digest)!=0)return 7;if(digest!=ra.digest)return 8;return 0;}
